/bin/bash -lc "python3 - <<'PY'
import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
print('TOP KEYS',list(r))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k,json.dumps(v,indent=2))
c=r['context']
print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge_access_log']: print(k,json.dumps(v,indent=2))
print('HISTORY SUMMARY')
for t in c.get('history',[]):
 print(json.dumps({k:v for k,v in t.items() if k not in ['validation','candidate_diagnostics']},ensure_ascii=False))
 print('validation',json.dumps({k:v for k,v in t.get('validation',{}).items() if k not in ['slices','per_task'] }))
PY"

